import Foundation

#if canImport(Glibc)
    import Glibc
#elseif canImport(Darwin)
    import Darwin
#endif

/// A tmux server found listening on a socket.
public struct DiscoveredServer: Sendable, Hashable, Codable {
    public let socketPath: String
    public let processID: Int?
    public let sessionCount: Int

    public init(socketPath: String, processID: Int?, sessionCount: Int) {
        self.socketPath = socketPath
        self.processID = processID
        self.sessionCount = sessionCount
    }
}

/// The bounded result of scanning for tmux servers.
public struct ServerDiscovery: Sendable, Hashable, Codable {
    public let servers: [DiscoveredServer]
    /// Whether the scan stopped at its entry or socket-candidate ceiling.
    public let truncated: Bool
}

/// Finding the tmux servers already running on this machine.
///
/// Every other call in this library addresses a server the caller already
/// names. This is the one that answers "what is there?" — which a program
/// arriving in an unfamiliar environment cannot ask any other way, because a
/// tmux server is a socket on disk and nothing enumerates them.
public enum TmuxServers {
    /// The most socket candidates one discovery probes and can return.
    package static let maximumCandidates = 128
    private static let maximumInspectedEntries = 4_096
    private static let maximumConcurrentProbes = 8
    private static let defaultProbeTimeout = Duration.seconds(2)

    /// Where tmux puts sockets when nobody says otherwise.
    ///
    /// tmux builds this from the real user id, not the name, and honours
    /// `TMUX_TMPDIR` above it.
    public static func defaultDirectories(
        environment: [String: String] = ProcessInfo.processInfo.environment
    ) -> [String] {
        let parent = environment["TMUX_TMPDIR"].flatMap { $0.isEmpty ? nil : $0 } ?? "/tmp"
        return [(parent as NSString).appendingPathComponent("tmux-\(getuid())")]
    }

    /// Every server listening on a socket in `directories`.
    ///
    /// A socket file is not a running server: tmux leaves the file behind when
    /// it exits, so each candidate is asked whether it answers. One that does
    /// not answer within two seconds is left out rather than reported as an
    /// empty server. At most eight candidates are asked at once.
    ///
    /// - Parameters:
    ///   - directories: where to look. Defaults to
    ///     ``defaultDirectories(environment:)``.
    ///   - tmuxExecutable: the tmux to ask with.
    /// - Returns: At most 128 reachable servers and whether the scan stopped
    ///   before exhausting entries or candidates.
    /// - Throws: ``TmuxError/cancelled`` when the calling task is cancelled.
    public static func discover(
        in directories: [String]? = nil,
        tmuxExecutable: String = "tmux"
    ) async throws(TmuxError) -> ServerDiscovery {
        @Sendable func probe(_ path: String) async throws(TmuxError) -> DiscoveredServer? {
            let server: Server
            do {
                server = try Server(
                    socketPath: path,
                    tmuxExecutable: tmuxExecutable
                )
            } catch {
                return nil
            }
            let sessions: [Session]
            do {
                sessions = try await server.sessions()
            } catch let error {
                if error == .cancelled { throw error }
                return nil
            }
            if sessions.isEmpty {
                guard try await server.isRunning() else { return nil }
            }
            let processID: Int?
            do {
                processID = try await server.serverProcessID()
            } catch let error {
                if error == .cancelled { throw error }
                processID = nil
            }
            return DiscoveredServer(
                socketPath: path,
                processID: processID,
                sessionCount: sessions.count
            )
        }
        return try await discover(
            in: directories,
            probeTimeout: defaultProbeTimeout,
            probe: probe
        )
    }

    static func discover(
        in directories: [String]? = nil,
        probeTimeout: Duration = defaultProbeTimeout,
        probe: @escaping @Sendable (String) async throws(TmuxError) -> DiscoveredServer?
    ) async throws(TmuxError) -> ServerDiscovery {
        let roots = directories ?? defaultDirectories()
        let scan = try scanCandidates(in: roots)

        if Task.isCancelled { throw .cancelled }
        return try await discover(
            candidates: scan.candidates,
            truncatedFromScan: scan.truncated,
            probeTimeout: probeTimeout,
            probe: probe
        )
    }

    private static func scanCandidates(
        in roots: [String]
    ) throws(TmuxError) -> CandidateScan {
        var scan = CandidateScan()
        roots: for root in roots {
            let rootURL = URL(fileURLWithPath: root, isDirectory: true)
            guard
                let entries = FileManager.default.enumerator(
                    at: rootURL,
                    includingPropertiesForKeys: nil,
                    options: [.skipsSubdirectoryDescendants]
                )
            else { continue }
            for case let entry as URL in entries {
                if Task.isCancelled { throw .cancelled }
                let path = (rootURL.path as NSString).appendingPathComponent(
                    entry.lastPathComponent
                )
                guard scan.inspect(path, isSocket: isSocket(at:)) else { break roots }
            }
        }
        return scan
    }

    static func discover<Entries: Sequence>(
        entries: Entries,
        isSocket: (String) -> Bool,
        probeTimeout: Duration = defaultProbeTimeout,
        probe: @escaping @Sendable (String) async throws(TmuxError) -> DiscoveredServer?
    ) async throws(TmuxError) -> ServerDiscovery where Entries.Element == String {
        var scan = CandidateScan()
        for entry in entries {
            if Task.isCancelled { throw .cancelled }
            guard scan.inspect(entry, isSocket: isSocket) else { break }
        }
        return try await discover(
            candidates: scan.candidates,
            truncatedFromScan: scan.truncated,
            probeTimeout: probeTimeout,
            probe: probe
        )
    }

    static func discover(
        candidates discoveredCandidates: [String],
        truncatedFromScan: Bool = false,
        probeTimeout: Duration = defaultProbeTimeout,
        probe: @escaping @Sendable (String) async throws(TmuxError) -> DiscoveredServer?
    ) async throws(TmuxError) -> ServerDiscovery {
        let truncated = truncatedFromScan || discoveredCandidates.count > maximumCandidates
        let candidates = Array(discoveredCandidates.prefix(maximumCandidates))
        do {
            return try await withThrowingTaskGroup(of: DiscoveredServer?.self) { group in
                var nextCandidate = 0
                for _ in 0..<min(maximumConcurrentProbes, candidates.count) {
                    let path = candidates[nextCandidate]
                    nextCandidate += 1
                    group.addTask {
                        try await probeCandidate(path, timeout: probeTimeout, using: probe)
                    }
                }
                var found: [DiscoveredServer] = []
                while let server = try await group.next() {
                    if Task.isCancelled {
                        group.cancelAll()
                        throw TmuxError.cancelled
                    }
                    if let server { found.append(server) }
                    if nextCandidate < candidates.count {
                        let path = candidates[nextCandidate]
                        nextCandidate += 1
                        group.addTask {
                            try await probeCandidate(path, timeout: probeTimeout, using: probe)
                        }
                    }
                }
                return ServerDiscovery(
                    servers: found.sorted { $0.socketPath < $1.socketPath },
                    truncated: truncated
                )
            }
        } catch {
            throw normalizedTmuxError(error)
        }
    }

    private static func probeCandidate(
        _ path: String,
        timeout: Duration,
        using probe: @escaping @Sendable (String) async throws(TmuxError) -> DiscoveredServer?
    ) async throws(TmuxError) -> DiscoveredServer? {
        if Task.isCancelled { throw .cancelled }
        do {
            let completion = try await withThrowingTaskGroup(of: ProbeCompletion.self) { group in
                group.addTask { .result(try await probe(path)) }
                group.addTask {
                    try await Task.sleep(for: timeout)
                    return .timedOut
                }
                defer { group.cancelAll() }
                return try await group.next() ?? .timedOut
            }
            if Task.isCancelled { throw TmuxError.cancelled }
            switch completion {
            case let .result(server): return server
            case .timedOut: return nil
            }
        } catch let error as TmuxError {
            if error == .cancelled { throw error }
            return nil
        } catch {
            if error is CancellationError || Task.isCancelled { throw .cancelled }
            return nil
        }
    }

    private enum ProbeCompletion: Sendable {
        case result(DiscoveredServer?)
        case timedOut
    }

    private static func isSocket(at path: String) -> Bool {
        var status = stat()
        guard lstat(path, &status) == 0 else { return false }
        return status.st_mode & mode_t(S_IFMT) == mode_t(S_IFSOCK)
    }

    private struct CandidateScan {
        var candidates: [String] = []
        var truncated = false
        private var inspectedEntries = 0
        private var seen: Set<String> = []

        mutating func inspect(_ path: String, isSocket: (String) -> Bool) -> Bool {
            guard inspectedEntries < TmuxServers.maximumInspectedEntries else {
                truncated = true
                return false
            }
            inspectedEntries += 1
            guard isSocket(path), seen.insert(path).inserted else { return true }
            candidates.append(path)
            guard candidates.count <= TmuxServers.maximumCandidates else {
                truncated = true
                return false
            }
            return true
        }
    }
}

Sources/LibTmux/Endpoint.swift.content:
/// Where a tmux server listens.
///
/// tmux resolves a *name* against `$TMUX_TMPDIR` at exec time, so the same name
/// can denote different servers in different environments. A *path* denotes one
/// socket. The two are mutually exclusive, and a value of either kind is always
/// addressable — the length check that a path must pass happens here rather
/// than at bind time, where it would surface as an opaque failure.
public enum Endpoint: Sendable, Hashable, Codable {
    case socketName(String)
    case socketPath(String)

    public init(socketName: String) throws(TmuxError) {
        guard !socketName.isEmpty else {
            throw .invalidEndpoint(.empty)
        }
        self = .socketName(socketName)
    }

    public init(socketPath: String) throws(TmuxError) {
        guard !socketPath.isEmpty else {
            throw .invalidEndpoint(.empty)
        }
        // `sun_path` is 104 bytes on the BSDs and 108 on Linux; the portable
        // budget is the smaller one, minus its terminator.
        let byteCount = socketPath.utf8.count
        guard byteCount <= Endpoint.portableSocketPathByteLimit else {
            throw .invalidEndpoint(
                .socketPathTooLong(
                    actualBytes: byteCount,
                    maximumBytes: Endpoint.portableSocketPathByteLimit
                )
            )
        }
        self = .socketPath(socketPath)
    }

    /// The longest socket path this library will accept, in bytes.
    ///
    /// A UNIX socket path lives in a fixed array in the kernel, and the two
    /// supported systems size it differently: 108 bytes on Linux, 104 on
    /// Darwin. The smaller of the two, less the terminating NUL, is what a
    /// path can be and still bind on either — so the check is the same
    /// wherever it runs, and a path that works on one machine is not rejected
    /// on the next. Exceeding it fails at bind time, far from the call that
    /// chose the path, which is why this is checked up front.
    public static let portableSocketPathByteLimit = 103

    /// The argv pair that addresses this endpoint. tmux is always launched with
    /// an explicit endpoint so a caller can never reach the ambient server by
    /// accident.
    var addressArguments: [String] {
        switch self {
        case let .socketName(name): ["-L", name]
        case let .socketPath(path): ["-S", path]
        }
    }
}

Sources/LibTmux/Environment.swift.content:
/// Which environment a variable lives in.
///
/// tmux keeps two, and only two: one global, and one per session. There is no
/// window or pane environment, so this cannot ask for one — unlike
/// ``OptionScope``, whose four tables are all real.
public enum EnvironmentScope: Sendable, Hashable, Codable {
    case global
    /// A session's own environment, addressed by name or id.
    case session(String)

    var arguments: [String] {
        switch self {
        case .global: ["-g"]
        case let .session(target): ["-t", target]
        }
    }
}

/// One variable in a tmux environment.
///
/// tmux prints two shapes, and they mean different things: `NAME=value` is a
/// variable with a value, and `-NAME` is one marked so that new processes start
/// *without* it, which is not the same as it being absent. Folding both into a
/// dictionary of strings would turn the second into a variable whose name
/// begins with a dash.
public struct TmuxEnvironmentVariable: Sendable, Hashable, Codable {
    /// The variable's name, without the `-` that marks a removal in tmux's
    /// own listing.
    public let name: String
    /// What a new process would be given, or `nil` when this variable is marked
    /// for removal instead. Ask ``isRemoved`` rather than testing for `nil`
    /// where the distinction is the point.
    public let value: String?

    public init(name: String, value: String?) {
        self.name = name
        self.value = value
    }

    /// Whether tmux will strip this variable from a new process's environment
    /// rather than set it.
    public var isRemoved: Bool { value == nil }
}

extension Server {
    /// `--` ends the flags, so a name beginning with `-` reaches tmux as a
    /// name rather than as flags it does not have.
    private func setEnvironmentCommand(
        _ name: String, to value: String, in scope: EnvironmentScope
    ) -> TmuxCommand {
        TmuxCommand("set-environment", scope.arguments + ["--", name, value])
    }

    /// Sets a variable in a session's environment, refusing if that session is
    /// no longer the one this value names.
    package func setEnvironment(
        _ name: String, to value: String, in session: Session
    ) async throws(TmuxError) -> TmuxReply {
        try await runGuarded(
            setEnvironmentCommand(name, to: value, in: .session(session.id.rawValue)),
            by: [.session(session)])
    }

    /// Every variable in an environment, in the order tmux printed them.
    public func environment(
        _ scope: EnvironmentScope = .global
    ) async throws(TmuxError) -> [TmuxEnvironmentVariable] {
        let reply = try await run(TmuxCommand("show-environment", scope.arguments))
        guard reply.isSuccess else { return [] }
        return reply.text
            .split(separator: "\n", omittingEmptySubsequences: true)
            .compactMap { TmuxEnvironmentVariable(line: String($0)) }
    }

    /// What one variable is set to, or `nil` when it is unset or marked for
    /// removal.
    ///
    /// Reads one value directly so embedded newlines remain part of that value.
    /// tmux's nonzero response for an unknown name becomes `nil`.
    public func environmentValue(
        _ name: String,
        in scope: EnvironmentScope = .global
    ) async throws(TmuxError) -> String? {
        let command = TmuxCommand("show-environment", scope.arguments + ["--", name])
        let reply = try await run(command)
        guard reply.isSuccess else {
            if reply.errorText == "unknown variable: \(name)" { return nil }
            throw reply.failure(for: command)
        }
        var text = reply.text
        if text.hasSuffix("\n") { text.removeLast() }
        if text == "-\(name)" { return nil }
        let prefix = "\(name)="
        guard text.hasPrefix(prefix) else {
            throw .invocationFailed(reason: "show-environment returned an unexpected variable.")
        }
        return String(text.dropFirst(prefix.count))
    }

    /// Sets a variable, replacing whatever was there.
    @discardableResult
    public func setEnvironment(
        _ name: String,
        to value: String,
        in scope: EnvironmentScope = .global
    ) async throws(TmuxError) -> TmuxReply {
        // run(_:) hands argv to tmux, which ends a command at a trailing `;`.
        // A guarded request is quoted as a command string and needs no escape.
        try await run(setEnvironmentCommand(name, to: tmuxArgumentData(value), in: scope))
    }

    /// Unsets a variable, leaving no trace of it.
    ///
    /// Different from ``removeEnvironment(_:in:)``: an unset variable is simply
    /// gone, where a removed one is still listed so that new processes are
    /// started without it.
    @discardableResult
    public func unsetEnvironment(
        _ name: String,
        in scope: EnvironmentScope = .global
    ) async throws(TmuxError) -> TmuxReply {
        try await run(
            TmuxCommand("set-environment", scope.arguments + ["-u", name])
        )
    }

    /// Marks a variable so new processes start without it, even when it is set
    /// in the environment tmux itself was started from.
    @discardableResult
    public func removeEnvironment(
        _ name: String,
        in scope: EnvironmentScope = .global
    ) async throws(TmuxError) -> TmuxReply {
        try await run(
            TmuxCommand("set-environment", scope.arguments + ["-r", name])
        )
    }
}

extension TmuxEnvironmentVariable {
    /// Reads one line of `show-environment`.
    init?(line: String) {
        if line.hasPrefix("-") {
            let name = String(line.dropFirst())
            guard !name.isEmpty else { return nil }
            self.init(name: name, value: nil)
            return
        }
        // Split on the first `=` only: a value is allowed to contain more.
        guard let separator = line.firstIndex(of: "=") else { return nil }
        let name = String(line[line.startIndex..<separator])
        guard !name.isEmpty else { return nil }
        self.init(name: name, value: String(line[line.index(after: separator)...]))
    }
}

Sources/LibTmux/FilteredListings.swift.content:
/// Why a filtered listing failed.
///
/// Two independent things can go wrong, and collapsing them would hide which:
/// tmux can refuse the listing, and a regular expression in the filter can
/// exhaust its budget while the results are being narrowed.
///
/// Shaped like ``OutputWaitError`` for the same reason it is — a caller that
/// only cares about one of the two should not have to unwrap a string.
public enum FilteredListingError: Error, Sendable, Hashable {
    case tmux(TmuxError)
    case matching(RegexMatchError)
}

/// Listings tmux narrows before they cross the process boundary.
///
/// ``Server/panes()`` reads every pane on the server and hands them all back;
/// filtering afterwards means the rows you discard were still formatted, piped,
/// and decoded. These take the filter with them: tmux evaluates as much of it
/// as its format language can express and returns only the rows that survive.
///
/// ```swift
/// let editors = try await server.panes(
///     where: .where(\.currentCommand, .isIn(["nvim", "vim"]))
/// )
/// ```
///
/// The answer is identical to filtering at home. Lowering is deliberately
/// incomplete — a regular expression runs on this package's bounded engine
/// rather than tmux's, so it is left out of the predicate — and whatever tmux
/// could not decide is decided here, on the smaller set it returned. tmux
/// narrows; Swift still has the last word.
extension Server {
    /// Sessions matching `expression`.
    public func sessions(
        where expression: FilterExpr<Session>
    ) async throws(FilteredListingError) -> [Session] {
        try await filtered(
            expression,
            listing: { predicate in
                TmuxCommand(
                    "list-sessions",
                    ["-f", predicate, "-F", Session.projection.template]
                )
            },
            projection: Session.projection,
            row: { Session(row: $0, endpoint: self.endpoint) }
        )
    }

    /// Windows matching `expression`.
    ///
    /// A window linked into more than one session appears once, as in
    /// ``windows()``.
    public func windows(
        where expression: FilterExpr<Window>
    ) async throws(FilteredListingError) -> [Window] {
        var seen: Set<WindowID> = []
        return try await filtered(
            expression,
            listing: { predicate in
                TmuxCommand(
                    "list-windows",
                    ["-a", "-f", predicate, "-F", WindowAppearance.projection.template]
                )
            },
            projection: WindowAppearance.projection,
            row: { WindowAppearance(row: $0, endpoint: self.endpoint).window }
        ).filter { seen.insert($0.id).inserted }
    }

    /// Panes matching `expression`.
    public func panes(
        where expression: FilterExpr<Pane>
    ) async throws(FilteredListingError) -> [Pane] {
        var seen: Set<PaneID> = []
        return try await filtered(
            expression,
            listing: { predicate in
                TmuxCommand(
                    "list-panes",
                    ["-a", "-f", predicate, "-F", Pane.projection.template]
                )
            },
            projection: Pane.projection,
            row: { Pane(row: $0, endpoint: self.endpoint) }
        ).filter { seen.insert($0.id).inserted }
    }

    /// Clients matching `expression`.
    ///
    /// The one listing here that does not push its filter to tmux. `-f` reached
    /// `list-clients` in tmux 3.4, three releases after this package's floor,
    /// and asking an older server for it fails the whole listing rather than
    /// being ignored. Version-gating it would buy nothing worth the round trip:
    /// a server has one client per attachment, so there is no long list to
    /// narrow. The expression is applied here, and the answer is the same.
    public func clients(
        where expression: FilterExpr<Client>
    ) async throws(FilteredListingError) -> [Client] {
        try await filtered(
            expression,
            listing: { _ in
                TmuxCommand("list-clients", ["-F", Client.projection.template])
            },
            projection: Client.projection,
            row: { Client(row: $0, endpoint: self.endpoint) }
        )
    }

    /// Runs a listing narrowed by `expression`, then applies it exactly.
    ///
    /// The second pass is not a fallback — it is what makes the first one safe
    /// to approximate. Skipping it when the predicate happens to be exact would
    /// buy a pass over an already-short array and cost the invariant that this
    /// and the local `filter(_:)` cannot disagree.
    private func filtered<Element: Filterable>(
        _ expression: FilterExpr<Element>,
        listing: (String) -> TmuxCommand,
        projection: FormatProjection,
        row: (FormatRow) -> Element
    ) async throws(FilteredListingError) -> [Element] {
        let command = listing(expression.tmuxPredicate)
        let reply: TmuxReply
        do {
            reply = try await run(command)
        } catch {
            throw .tmux(error)
        }
        // A filter that excluded every row is still a success: tmux exits 0
        // and prints nothing, on every supported release. So a nonzero status
        // is a failure with no ambiguity to resolve — treating an empty
        // standard error as "matched nothing" would report absence for a
        // client that was killed before it could say anything.
        guard reply.isSuccess else {
            throw .tmux(reply.failure(for: command))
        }
        let rows: [FormatRow]
        do {
            rows = try projection.decode(reply.standardOutput)
        } catch {
            throw .tmux(.decodingFailed(error))
        }
        do {
            return try rows.map(row).filter(expression)
        } catch {
            throw .matching(error)
        }
    }
}

Sources/LibTmux/FilterExpr.swift.content:
import Foundation

/// A value a filter can compare against.
public enum FilterValue: Sendable, Hashable, Codable {
    case text(String)
    case integer(Int)
    case flag(Bool)
}

/// A model that can be filtered declaratively.
///
/// Key paths are lowered to stable ids inside a synchronous call and then
/// discarded. Nothing stores one: `AnyKeyPath` is a non-`Sendable` class, so
/// keeping it would make every expression that held it unsendable, and an
/// expression's whole purpose is to travel.
public protocol Filterable: Sendable {
    /// The stable wire id for a key path, or `nil` if the property is not
    /// filterable.
    static func filterFieldID(for keyPath: PartialKeyPath<Self>) -> String?

    /// Reads the field an id names, or `nil` if this model has no such field.
    static func filterValue(_ id: String, of root: Self) -> FilterValue?

    /// The value kind an id names, or `nil` when this model does not know it.
    static func filterFieldType(_ id: String) -> FilterSchema.ValueType?

    /// The tmux format field an id reads, or `nil` when it has no single one.
    ///
    /// This is what lets a filter be answered by tmux instead of by listing
    /// everything and discarding most of it. Returning `nil` is always safe:
    /// the field drops out of the `-f` predicate and is evaluated in Swift.
    static func filterFormatField(_ id: String) -> String?
}

extension Filterable {
    /// No field lowers unless a model says so, so a conformance written before
    /// this existed keeps working and simply filters at home.
    public static func filterFormatField(_ id: String) -> String? { nil }
}

/// Why a filter could not be built.
public enum QueryConstructionError: Error, Sendable, Hashable {
    /// The key path does not name a filterable field of this model.
    case unknownField
    /// The field and operator could not form a safe expression.
    case invalidOperation(FilterValidationError)
}

/// Why a decoded filter cannot be evaluated safely.
public enum FilterValidationError: Error, Sendable, Hashable {
    case unknownField(String)
    case incompatibleOperation(
        field: String,
        type: FilterSchema.ValueType,
        operation: FilterOperation
    )
}

/// Why selecting one result from a filter failed.
public enum FilterSelectionError: Error, Sendable, Hashable {
    case matching(RegexMatchError)
    case cardinality(CardinalityError)
}

/// How a filter compares one field.
///
/// Written as a wire value rather than a closure, so an expression can be
/// stored, sent, inspected, and later compiled to a tmux `-f` predicate.
/// A regular expression travels in compiled, bounded form.
public enum FilterOperation: Sendable, Hashable, Codable {
    case equals(FilterValue)
    case caseInsensitiveEquals(String)
    case contains(String)
    case caseInsensitiveContains(String)
    case hasPrefix(String)
    case hasSuffix(String)
    case isIn([FilterValue])
    case matches(pattern: RegexPattern)
}

/// A typed operator. The `Value` it is built for is the projected type of the
/// key path it is paired with, so pairing a text operator with an integer field
/// is a compile error rather than a runtime surprise.
public struct FilterOperator<Value>: Sendable {
    let operation: FilterOperation

    private init(_ operation: FilterOperation) {
        self.operation = operation
    }

    // MARK: Text

    public static func equals(_ value: String) -> Self where Value == String {
        Self(.equals(.text(value)))
    }

    public static func caseInsensitiveEquals(_ value: String) -> Self
    where Value == String {
        Self(.caseInsensitiveEquals(value))
    }

    public static func contains(_ value: String) -> Self where Value == String {
        Self(.contains(value))
    }

    public static func caseInsensitiveContains(_ value: String) -> Self
    where Value == String {
        Self(.caseInsensitiveContains(value))
    }

    public static func hasPrefix(_ value: String) -> Self where Value == String {
        Self(.hasPrefix(value))
    }

    public static func hasSuffix(_ value: String) -> Self where Value == String {
        Self(.hasSuffix(value))
    }

    public static func isIn(_ values: [String]) -> Self where Value == String {
        Self(.isIn(values.map(FilterValue.text)))
    }

    public static func matches(_ pattern: RegexPattern) -> Self where Value == String {
        Self(.matches(pattern: pattern))
    }

    // MARK: Typed identifiers

    public static func equals(_ value: SessionID) -> Self where Value == SessionID {
        Self(.equals(.text(value.rawValue)))
    }

    public static func isIn(_ values: [SessionID]) -> Self where Value == SessionID {
        Self(.isIn(values.map { .text($0.rawValue) }))
    }

    public static func equals(_ value: WindowID) -> Self where Value == WindowID {
        Self(.equals(.text(value.rawValue)))
    }

    public static func isIn(_ values: [WindowID]) -> Self where Value == WindowID {
        Self(.isIn(values.map { .text($0.rawValue) }))
    }

    public static func equals(_ value: PaneID) -> Self where Value == PaneID {
        Self(.equals(.text(value.rawValue)))
    }

    public static func isIn(_ values: [PaneID]) -> Self where Value == PaneID {
        Self(.isIn(values.map { .text($0.rawValue) }))
    }

    // MARK: Integer

    public static func equals(_ value: Int) -> Self where Value == Int {
        Self(.equals(.integer(value)))
    }

    public static func isIn(_ values: [Int]) -> Self where Value == Int {
        Self(.isIn(values.map(FilterValue.integer)))
    }

    // MARK: Flag

    public static func equals(_ value: Bool) -> Self where Value == Bool {
        Self(.equals(.flag(value)))
    }
}

/// A filter over one model, held as data.
///
/// `Sendable` and `Codable` because it is meant to outlive the call that built
/// it: stored in a config, sent to another process, or translated into a tmux
/// predicate. Closures deliberately have no place in it — they cannot be any of
/// those things.
public indirect enum FilterExpr<Root: Filterable>: Sendable, Hashable, Codable {
    case comparison(field: String, operation: FilterOperation)
    case and([FilterExpr<Root>])
    case or([FilterExpr<Root>])
    case not(FilterExpr<Root>)

    /// Builds a comparison from a key path.
    ///
    /// The key path is lowered to a stable field id here and then discarded —
    /// nothing downstream holds one, so an expression can cross a boundary a
    /// key path could not.
    public static func `where`<Value>(
        _ keyPath: KeyPath<Root, Value> & Sendable,
        _ operation: FilterOperator<Value>
    ) throws(QueryConstructionError) -> Self {
        guard let fieldID = Root.filterFieldID(for: keyPath) else {
            throw .unknownField
        }
        guard let type = Root.filterFieldType(fieldID) else { throw .unknownField }
        do {
            try operation.operation.validate(field: fieldID, type: type)
        } catch {
            throw .invalidOperation(error)
        }
        return .comparison(field: fieldID, operation: operation.operation)
    }

    /// Whether one value satisfies this filter.
    ///
    /// Evaluated against a value already in hand. Matching never reaches tmux,
    /// so iterating results cannot spawn a process.
    public func matches(_ root: Root) throws(RegexMatchError) -> Bool {
        try matches(root, budget: RegexMatchBudget())
    }

    package func matches(
        _ root: Root,
        budget: RegexMatchBudget
    ) throws(RegexMatchError) -> Bool {
        switch self {
        case let .comparison(fieldID, operation):
            guard let value = Root.filterValue(fieldID, of: root) else {
                return false
            }
            return try operation.matches(value, budget: budget)
        case let .and(children):
            for child in children {
                if try !child.matches(root, budget: budget) { return false }
            }
            return true
        case let .or(children):
            for child in children {
                if try child.matches(root, budget: budget) { return true }
            }
            return false
        case let .not(child):
            return try !child.matches(root, budget: budget)
        }
    }

    /// Rejects field ids this build does not understand anywhere in the tree.
    public func validate() throws(FilterValidationError) {
        switch self {
        case let .comparison(fieldID, operation):
            guard let type = Root.filterFieldType(fieldID) else {
                throw .unknownField(fieldID)
            }
            try operation.validate(field: fieldID, type: type)
        case let .and(children), let .or(children):
            for child in children { try child.validate() }
        case let .not(child):
            try child.validate()
        }
    }
}

extension FilterOperation {
    func validate(
        field: String,
        type: FilterSchema.ValueType
    ) throws(FilterValidationError) {
        switch self {
        case let .equals(value):
            guard value.schemaType == type else {
                throw .incompatibleOperation(field: field, type: type, operation: self)
            }
        case let .isIn(values):
            guard values.allSatisfy({ $0.schemaType == type }) else {
                throw .incompatibleOperation(field: field, type: type, operation: self)
            }
        case .caseInsensitiveEquals, .contains, .caseInsensitiveContains, .hasPrefix,
            .hasSuffix:
            guard type == .text else {
                throw .incompatibleOperation(field: field, type: type, operation: self)
            }
        case .matches:
            guard type == .text else {
                throw .incompatibleOperation(field: field, type: type, operation: self)
            }
        }
    }

    func matches(
        _ value: FilterValue,
        budget: RegexMatchBudget
    ) throws(RegexMatchError) -> Bool {
        switch self {
        case let .equals(expected):
            return value == expected
        case let .caseInsensitiveEquals(expected):
            guard case let .text(text) = value else { return false }
            return text.lowercased() == expected.lowercased()
        case let .contains(expected):
            guard case let .text(text) = value else { return false }
            return text.contains(expected)
        case let .caseInsensitiveContains(expected):
            guard case let .text(text) = value else { return false }
            return text.lowercased().contains(expected.lowercased())
        case let .hasPrefix(expected):
            guard case let .text(text) = value else { return false }
            return text.hasPrefix(expected)
        case let .hasSuffix(expected):
            guard case let .text(text) = value else { return false }
            return text.hasSuffix(expected)
        case let .isIn(expected):
            return expected.contains(value)
        case let .matches(pattern):
            guard case let .text(text) = value else { return false }
            return try pattern.containsMatch(in: text, budget: budget)
        }
    }
}

extension FilterValue {
    fileprivate var schemaType: FilterSchema.ValueType {
        switch self {
        case .text: .text
        case .integer: .integer
        case .flag: .flag
        }
    }
}

// MARK: - Applying a filter

extension Sequence where Element: Filterable {
    /// Every element the filter matches, in order.
    ///
    /// Returns a plain array: ordered, replayable, and free of any live
    /// connection to tmux.
    public func filter(
        _ expression: FilterExpr<Element>
    ) throws(RegexMatchError) -> [Element] {
        try filter(expression, regexBudget: RegexMatchBudget())
    }

    package func filter(
        _ expression: FilterExpr<Element>,
        regexBudget: RegexMatchBudget
    ) throws(RegexMatchError) -> [Element] {
        var result: [Element] = []
        for element in self where try expression.matches(element, budget: regexBudget) {
            result.append(element)
        }
        return result
    }

    /// The one element the filter matches.
    ///
    /// Distinguishes "nothing matched" from "several matched", because a caller
    /// that meant to address one object needs to know which mistake it made.
    public func exactlyOne(
        _ expression: FilterExpr<Element>
    ) throws(FilterSelectionError) -> Element {
        let matches: [Element]
        do {
            matches = try filter(expression)
        } catch {
            throw .matching(error)
        }
        switch matches.count {
        case 0: throw .cardinality(.noMatch)
        case 1: return matches[0]
        default: throw .cardinality(.multipleMatches(count: matches.count))
        }
    }

    /// The one element the filter matches, or `nil` if none did.
    ///
    /// Only ambiguity is an error here; absence is an ordinary answer.
    public func oneOrNil(
        _ expression: FilterExpr<Element>
    ) throws(FilterSelectionError) -> Element? {
        let matches: [Element]
        do {
            matches = try filter(expression)
        } catch {
            throw .matching(error)
        }
        switch matches.count {
        case 0: return nil
        case 1: return matches[0]
        default: throw .cardinality(.multipleMatches(count: matches.count))
        }
    }
}

