/// One tmux command, as argv.
///
/// No shell sees the arguments. tmux still reads a trailing `;` as a command
/// separator; spell a literal trailing semicolon as `\;`.
public struct TmuxCommand: Sendable, Hashable {
    /// The tmux command, as tmux spells it — `new-session`, `list-panes`.
    public let name: String
    /// Its arguments, one element each. Never a joined string: a value holding
    /// a space is data.
    public let arguments: [String]
    public init(_ name: String, _ arguments: [String] = []) {
        self.name = name
        self.arguments = arguments
    }

    /// The command's own argv, without the endpoint tmux is addressed with.
    var argumentVector: [String] {
        [name] + arguments
    }

    /// A command argument that tmux will parse as another command.
    var parsedString: String {
        argumentVector.map(tmuxQuoted).joined(separator: " ")
    }
}

// tmux packs argv after a four-byte argc in its 16 KiB command message.
private let maximumTmuxCommandPayloadBytes = 16_380

func requireTmuxCommandFits(_ arguments: [String]) throws(TmuxError) {
    var actualBytes = 0
    for argument in arguments {
        let (argumentBytes, argumentOverflowed) = argument.utf8.count
            .addingReportingOverflow(1)
        let (nextBytes, totalOverflowed) = actualBytes.addingReportingOverflow(
            argumentBytes
        )
        guard !argumentOverflowed, !totalOverflowed else {
            throw .commandTooLarge(
                actualBytes: .max,
                maximumBytes: maximumTmuxCommandPayloadBytes
            )
        }
        actualBytes = nextBytes
    }
    guard actualBytes <= maximumTmuxCommandPayloadBytes else {
        throw .commandTooLarge(
            actualBytes: actualBytes,
            maximumBytes: maximumTmuxCommandPayloadBytes
        )
    }
}

/// What tmux said.
///
/// Output is bytes. tmux does not promise UTF-8 — a pane title can carry
/// anything the program in it emitted — so decoding is the caller's decision
/// and invalid bytes are data rather than a failure.
public struct TmuxReply: Sendable, Hashable {
    /// Bytes rather than a string, because a format's fields are separated by
    /// a byte and decoding happens after splitting, not before.
    public let standardOutput: [UInt8]
    /// Where tmux explains a command it refused.
    public let standardError: [UInt8]
    /// tmux's exit status. Nonzero is an answer — `has-session` says "no" this
    /// way — so it is reported rather than thrown.
    public let exitCode: Int32

    public init(standardOutput: [UInt8], standardError: [UInt8], exitCode: Int32) {
        self.standardOutput = standardOutput
        self.standardError = standardError
        self.exitCode = exitCode
    }

    public var isSuccess: Bool { exitCode == 0 }

    /// Standard output decoded as UTF-8, replacing anything invalid.
    public var text: String {
        String(decoding: standardOutput, as: UTF8.self)
    }

    /// Standard error decoded as UTF-8, trimmed of its trailing newline.
    public var errorText: String {
        var text = String(decoding: standardError, as: UTF8.self)
        if text.hasSuffix("\n") { text.removeLast() }
        return text
    }

    func failure(for command: TmuxCommand) -> TmuxError {
        .commandFailed(
            command: command.name,
            exitCode: exitCode,
            reason: errorText
        )
    }
}

Sources/LibTmux/TmuxContext.swift.content:
import Foundation

/// Where the tmux this process is running inside can be found.
///
/// tmux sets `$TMUX` in every process it starts, holding the socket, the
/// server's pid, and the session — which is how a program launched from a pane
/// can find its way back to the server that launched it without being told.
///
/// The session arrives as a bare number where ``Session/id`` carries tmux's
/// `$` sigil, so it is normalised here. Comparing the two spellings directly is
/// a mismatch that looks like a missing session.
public struct TmuxContext: Sendable, Hashable, Codable {
    /// The socket the surrounding server listens on, which is what addressing
    /// it again needs.
    public let socketPath: String
    /// The server process, which is the one thing here that distinguishes two
    /// servers that reused a socket path.
    public let serverProcessID: Int
    /// The session, normalised to the spelling ``Session/id`` uses.
    public let sessionID: SessionID

    public init(socketPath: String, serverProcessID: Int, sessionID: SessionID) {
        self.socketPath = socketPath
        self.serverProcessID = serverProcessID
        self.sessionID = sessionID
    }

    /// Reads the value tmux puts in `$TMUX`.
    ///
    /// Returns `nil` for anything that is not that shape, including an empty
    /// string: a process not started by tmux has no context to report, and
    /// inventing one would point at a server that may not exist.
    public init?(parsing tmuxVariable: String) {
        // Split from the right: the last two fields are numbers, and the first
        // is a path, which is the only field allowed to contain a comma.
        let parts = tmuxVariable.split(separator: ",", omittingEmptySubsequences: false)
        guard parts.count >= 3 else { return nil }

        let rawProcessID = parts[parts.count - 2]
        guard rawProcessID.first.map({ "1"..."9" ~= $0 }) == true,
            rawProcessID.allSatisfy({ "0"..."9" ~= $0 }),
            let processID = Int(rawProcessID)
        else { return nil }

        let rawSessionID = parts[parts.count - 1]
        guard
            rawSessionID == "0"
                || (rawSessionID.first.map({ "1"..."9" ~= $0 }) == true
                    && rawSessionID.allSatisfy({ "0"..."9" ~= $0 }))
        else { return nil }

        let path = parts[0..<(parts.count - 2)].joined(separator: ",")
        guard path.utf8.first == 0x2f,
            !path.utf8.contains(where: { $0 < 0x20 || $0 == 0x7f })
        else { return nil }

        guard
            let sessionID = SessionID(
                rawValue: "$\(rawSessionID)"
            )
        else { return nil }

        self.init(
            socketPath: path,
            serverProcessID: processID,
            sessionID: sessionID
        )
    }

    /// The context of the tmux this process is running inside, or `nil` when it
    /// is not running inside one.
    ///
    /// - Parameter environment: where to read `$TMUX` from. Injectable so that
    ///   a caller — or a test — can ask about an environment other than its own.
    public static func current(
        environment: [String: String] = ProcessInfo.processInfo.environment
    ) -> TmuxContext? {
        guard let value = environment["TMUX"] else { return nil }
        return TmuxContext(parsing: value)
    }

    /// A server addressed at this context's socket.
    ///
    /// Separate from reading the context because addressing can fail — a socket
    /// path has a hard length limit — where reading an environment variable
    /// cannot.
    public func server(tmuxExecutable: String = "tmux") throws(TmuxError) -> Server {
        try Server(socketPath: socketPath, tmuxExecutable: tmuxExecutable)
    }
}

Sources/LibTmux/TmuxError.swift.content:
/// Everything a tmux operation can fail with.
///
/// ``Server/run(_:)-(TmuxCommand)`` hands every tmux status back as a
/// ``TmuxReply``. Higher-level operations that promise a decoded value throw
/// ``commandFailed(command:exitCode:reason:)`` when tmux rejects that read.
public enum TmuxError: Error, Sendable, Hashable {
    /// The tmux client process was never started, so the requested command
    /// cannot have reached a daemon.
    case processLaunchFailed(reason: String)

    /// A control connection closed before the command was enqueued. Retrying
    /// cannot duplicate the requested action because tmux never received it.
    case requestNotSubmitted

    /// No usable reply was obtained after submission. Unless a narrower error
    /// says otherwise, the action may have reached tmux.
    case invocationFailed(reason: String)

    /// A direct tmux client cannot encode the command, so it was not submitted.
    case commandTooLarge(actualBytes: Int, maximumBytes: Int)

    /// tmux received a typed command but rejected it.
    ///
    /// Only the command name is retained; arguments may contain pane text,
    /// environment values, or other caller data that does not belong in an error.
    case commandFailed(command: String, exitCode: Int32, reason: String)

    /// A reply exceeded its finite per-stream memory boundary.
    case outputLimitExceeded(perStreamBytes: Int)

    /// The endpoint is not addressable. A UNIX socket path has a hard length
    /// limit far shorter than the filesystem's, and exceeding it fails at bind
    /// time rather than at construction.
    case invalidEndpoint(InvalidEndpoint)

    /// tmux replied, but the reply did not match the requested projection.
    case decodingFailed(FormatDecodingError)

    /// The reply arrived from a different server than the one the request was
    /// prepared against.
    case serverRestarted

    /// A value from another endpoint cannot target this server.
    case foreignServerValue

    /// A target no longer names the object or context the value described.
    case staleServerValue

    /// The task was cancelled. A cancelled request never reports an empty
    /// listing — that would be indistinguishable from a server with no
    /// sessions.
    case cancelled

    /// A control-mode connection ended while a command was still waiting.
    ///
    /// Distinct from ``serverRestarted``: tmux says `%exit` when it is
    /// closing this client — because the session it was attached to went
    /// away, or the server is shutting down — which says nothing about a
    /// replacement daemon having appeared.
    case connectionClosed

    /// An observer did not drain control notifications before its finite
    /// buffer filled. Earlier buffered notifications remain readable.
    case notificationBufferOverflow(limit: Int)

    /// A pane changed beyond the retained checkpoint while output was being
    /// watched, so new rows cannot be separated from rows already seen.
    case outputContinuityLost

    public enum InvalidEndpoint: Sendable, Hashable {
        case empty
        case socketPathTooLong(actualBytes: Int, maximumBytes: Int)
    }
}

/// A tmux reply that did not match its projection.
///
/// Each case names the row it failed on, so a caller can attribute a failure to
/// one object rather than discarding the whole listing.
public enum FormatDecodingError: Error, Sendable, Hashable {
    case fieldCountMismatch(rowIndex: Int, expected: Int, actual: Int)
    case invalidEncoding(rowIndex: Int)
    case invalidValue(rowIndex: Int, field: String, raw: String)
}

/// Why a lookup that expected exactly one match did not get one.
public enum CardinalityError: Error, Sendable, Hashable {
    case noMatch
    case multipleMatches(count: Int)
}

Sources/LibTmux/TmuxMode.swift.content:
/// How work reaches tmux.
///
/// One dial with two settings. Choosing one never changes the call you write or
/// the type you get back — ``Server/sessions()`` returns `[Session]` either way.
/// What changes is whether that crossed a process boundary or a connection that
/// was already open.
///
/// | Mode | What it does | When it wins |
/// | --- | --- | --- |
/// | ``direct`` | A tmux process per call | One call, or calls far apart |
/// | ``connected(to:)`` | One live connection for the scope | More than one call, and anything that wants to be told what changed |
///
/// ``Server/using(_:_:)`` takes one of these, so a program that decides at
/// runtime — a flag, a config file, a benchmark measuring both — writes the
/// choice as data instead of branching around two shapes of call.
public enum TmuxMode: Sendable, Hashable {
    /// A tmux process per call. The default, and the one nothing has to say.
    case direct

    /// One control-mode connection carrying every call in the scope.
    ///
    /// The session is part of the mode rather than a separate argument, because
    /// a connection is a client and tmux has no client attached to nothing: one
    /// with no target runs tmux's default command and *creates* a session. The
    /// session named here must already exist.
    case connected(to: String)
}

Sources/LibTmux/TmuxVersion.swift.content:
import Foundation

/// A tmux release, ordered the way tmux numbers them.
///
/// The trailing letter is part of the version, not decoration: tmux 3.7 shipped
/// a `break-pane` crash that 3.7a reverted, so code that has to know which one
/// it is talking to needs `3.7 < 3.7a` to be true. Comparing on the numbers
/// alone would make those two equal and the question unanswerable.
public struct TmuxVersion: Sendable, Hashable, Comparable, Codable {
    /// The major version — `3` in `3.7a`.
    public let major: Int
    /// The minor version — `7` in `3.7a`.
    public let minor: Int
    /// The point release's letter — `a` in `3.7a` — empty when there is none.
    /// Ordered as tmux issues them, so no letter precedes `a` precedes `b`.
    public let pointRelease: String
    /// What tmux was built from when it is not a release: `master` for a git
    /// build, `openbsd` for the one in OpenBSD's base system. Absent otherwise.
    public let build: String?

    public init(major: Int, minor: Int, pointRelease: String = "", build: String? = nil) {
        self.major = major
        self.minor = minor
        self.pointRelease = pointRelease
        self.build = build
    }

    /// Reads what `tmux -V` prints.
    ///
    /// Returns `nil` rather than guessing: a version this cannot read is a tmux
    /// whose behaviour this library has no basis to predict, and defaulting to
    /// "probably recent" is how a workaround silently stops being applied.
    public init?(parsing text: String) {
        var body = text.trimmingCharacters(in: .whitespacesAndNewlines)
        if body.hasPrefix("tmux ") { body = String(body.dropFirst(5)) }

        // `next-3.8` is tmux's own prefix for a pre-release; `3.4-master` and
        // `3.4-openbsd` are suffixes. Either way the tag is not the number.
        var build: String?
        if let dash = body.firstIndex(of: "-") {
            let before = String(body[body.startIndex..<dash])
            let after = String(body[body.index(after: dash)...])
            if Int(before.prefix(1)) == nil, !before.isEmpty {
                build = before
                body = after
            } else {
                build = after
                body = before
            }
        }

        let parts = body.split(separator: ".", maxSplits: 1, omittingEmptySubsequences: false)
        guard parts.count == 2, let major = Int(parts[0]) else { return nil }

        let tail = parts[1]
        let digits = tail.prefix { $0.isNumber }
        guard !digits.isEmpty, let minor = Int(digits) else { return nil }
        let letters = String(tail.dropFirst(digits.count))
        guard letters.allSatisfy({ $0.isLetter }) else { return nil }

        self.init(major: major, minor: minor, pointRelease: letters, build: build)
    }

    public static func < (lhs: TmuxVersion, rhs: TmuxVersion) -> Bool {
        let lhsKey = (lhs.major, lhs.minor, lhs.pointRelease)
        let rhsKey = (rhs.major, rhs.minor, rhs.pointRelease)
        if lhsKey != rhsKey { return lhsKey < rhsKey }
        // `next-X.Y` names what master will become, not a release; every
        // other build (`rc`, `openbsd`, `master`) already happened at that
        // number, so only this one ranks below it.
        return lhs.build == "next" && rhs.build != "next"
    }
}

extension TmuxVersion: CustomStringConvertible {
    public var description: String {
        let release = "\(major).\(minor)\(pointRelease)"
        return build.map { "\(release)-\($0)" } ?? release
    }
}

extension Server {
    /// Which tmux this server runs.
    ///
    /// Read from the binary rather than from a running daemon, so it answers
    /// before anything is started. A build this library cannot parse throws
    /// rather than reporting a version it guessed.
    public func version() async throws(TmuxError) -> TmuxVersion {
        let reply = try await run(rawArguments: ["-V"])
        guard let version = TmuxVersion(parsing: reply.text) else {
            throw .invocationFailed(
                reason: "could not read a tmux version from \(reply.text.debugDescription)"
            )
        }
        return version
    }
}

Sources/LibTmux/TypedErrorScope.swift.content:
/// Narrowing a scope's thrown type back to ``TmuxError``.
///
/// Every call in this library throws ``TmuxError`` and says so, which lets a
/// program write `throws(TmuxError)` from top to bottom. The scoped forms —
/// ``Server/using(_:_:)``, ``Server/connected(attachingTo:_:)`` and
/// ``Server/withControlMode(attachingTo:_:)`` — are the exception: they take a
/// closure, and a closure's thrown type cannot be carried out of one.
///
/// That is a property of the language rather than a choice made here. Swift
/// 6.2 does not infer a closure literal's thrown type from its body, so a
/// `throws(TmuxError)` overload of those scopes is unreachable without spelling
/// the closure's own signature at every call site — and even with the type
/// inferred, a scope that can fail on its own behalf has no way to rethrow that
/// failure as the body's error, because there is no union of the two.
///
/// So the narrowing happens at the boundary instead of inside the scope:
///
/// ```swift
/// func names(_ server: Server) async throws(TmuxError) -> [String] {
///     try await withTmuxError {
///         try await server.using(.connected(to: "main")) { server in
///             try await server.sessions().map(\.name)
///         }
///     }
/// }
/// ```
///
/// One wrapper per scope, rather than an annotation per closure.
///
/// - Important: This is for work that only fails with ``TmuxError``. Anything
///   else `body` throws is flattened into
///   ``TmuxError/invocationFailed(reason:)`` with its description as the
///   reason, which keeps the signature honest but loses the original type. A
///   body that throws errors of its own should stay untyped and be caught as
///   itself.
///
/// - Parameter body: the work to run, typically a scoped call.
/// - Returns: whatever `body` returned.
/// - Throws: ``TmuxError``, either as thrown or as a flattened foreign error.
public func withTmuxError<Result>(
    _ body: () async throws -> Result
) async throws(TmuxError) -> Result {
    try await withTmuxErrorMapping(body)
}

Sources/LibTmux/Wait.swift.content:
/// Synchronising with work tmux is running for you.
///
/// A pane runs a shell, and a shell says nothing about when it is finished.
/// Watching the pane for a prompt guesses; a channel does not. The command you
/// start signals when it is done, and ``Server/wait(for:)`` returns at that
/// point rather than on a timer.
///
/// ```swift
/// try await server.run(
///     "make; \(server.shellInvocation) wait-for -S built",
///     in: pane
/// )
/// try await server.wait(for: "built")
/// ```
///
/// Channels are named by whoever uses them and are shared across the whole
/// server, so a name wants to be specific enough that two unrelated pieces of
/// work do not pick the same one.
extension Server {
    /// Blocks until something signals `channel`.
    ///
    /// Runs in a process of its own even on a connected server, because a
    /// control client runs one command at a time: carried over the connection
    /// this would hold back every call beside it, ``Server/signal(_:)``
    /// included, and nothing would ever release it.
    ///
    /// - Throws: ``TmuxError/serverRestarted`` if the server went away while
    ///   this was waiting. tmux releases its waiters when it shuts down, with
    ///   the same silent success a real signal produces, so the server's
    ///   identity before and after is what tells a release from a departure.
    ///   ``TmuxError/cancelled`` if the task was cancelled, which ends the
    ///   wait without a signal.
    public func wait(for channel: String) async throws(TmuxError) {
        let before = try await serverProcessID()
        let reply = try await runInOwnProcess(
            rawArguments: TmuxCommand("wait-for", ["--", channel]).argumentVector
        )
        guard reply.isSuccess else {
            throw .invocationFailed(reason: reply.errorText)
        }
        let after = try await serverProcessID()
        guard before == after else {
            throw .serverRestarted
        }
    }

    /// Releases one waiter on `channel`.
    ///
    /// Signalling a channel nobody is waiting on does not queue: it leaves the
    /// channel ready, so the next wait returns at once and spends it. A second
    /// signal puts the channel back rather than storing a second release, so
    /// an unpaired signal is worth avoiding — what a later wait does depends
    /// on how many went unmatched, not how many were sent.
    public func signal(_ channel: String) async throws(TmuxError) {
        try await expectSuccess(TmuxCommand("wait-for", ["-S", "--", channel]))
    }
}

Sources/LibTmux/WaitForOutput.swift.content:
import Foundation

/// What a wait on a pane's output ended on.
public struct OutputWait: Sendable, Hashable, Codable {
    public enum Outcome: String, Sendable, Hashable, Codable {
        /// One of `patterns` appeared in output that arrived during the wait.
        case matched
        /// One of `stops` appeared first. `matchedIndex` says which.
        case stopped
        /// Nothing matched before the deadline, in reads that finished.
        case timedOut
        /// The deadline arrived while a read of the pane was still in flight,
        /// so the wait never finished looking.
        ///
        /// This is not ``timedOut``: it does not say the pattern failed to
        /// appear, only that there was not time to find out. It answers a
        /// timeout shorter than a tmux round-trip — including a zero one —
        /// and a machine loaded enough to make an ordinary read miss an
        /// ordinary deadline. Retrying with a longer timeout is the fix;
        /// changing the pattern is not.
        case expiredWhileReading
        /// The pane went away, so nothing more can arrive.
        case paneClosed
        /// A pager, editor, or other full-screen program owned the pane, so
        /// matching was suppressed for as long as it did.
        ///
        /// tmux fills that grid without adding to history, so what a capture
        /// returns is the program's paint rather than anything the pane
        /// printed — matching it reports text that was never written. Read the
        /// screen with ``Server/capture(_:includingHistory:)`` instead of retrying: a
        /// different pattern does not change what the wait is allowed to see.
        case alternateScreen
    }

    public let outcome: Outcome
    /// The pattern that ended the wait, from `patterns` or from `stops`.
    public let matched: String?
    /// Its position in whichever list it came from.
    public let matchedIndex: Int?
    /// Whether anything at all arrived. `false` with
    /// ``Outcome/timedOut`` means the pane was quiet — usually the command
    /// never ran, which no change of pattern will fix. Under
    /// ``Outcome/expiredWhileReading`` it says nothing: the reads that would
    /// have seen output did not finish.
    public let sawNewOutput: Bool
    /// A match or stop condition was already on screen when the wait began.
    /// It accompanies an immediate match or stop, or the later outcome when
    /// `requireFresh` made the wait look past it. Under
    /// ``Outcome/expiredWhileReading`` it is only meaningful if the entry
    /// screen itself was read.
    public let matchedAtEntry: Bool
    /// The last lines that arrived, newest last, for reading when the pattern
    /// was wrong.
    public let tail: [String]
    /// Hand this back to a later wait to carry on without re-reading these rows.
    public let cursor: CaptureCursor?
    public let seconds: Double

    public init(
        outcome: Outcome,
        matched: String? = nil,
        matchedIndex: Int? = nil,
        sawNewOutput: Bool,
        matchedAtEntry: Bool = false,
        tail: [String],
        cursor: CaptureCursor? = nil,
        seconds: Double
    ) {
        self.outcome = outcome
        self.matched = matched
        self.matchedIndex = matchedIndex
        self.sawNewOutput = sawNewOutput
        self.matchedAtEntry = matchedAtEntry
        self.tail = tail
        self.cursor = cursor
        self.seconds = seconds
    }

    func resuming(at cursor: CaptureCursor) -> OutputWait {
        OutputWait(
            outcome: outcome,
            matched: matched,
            matchedIndex: matchedIndex,
            sawNewOutput: sawNewOutput,
            matchedAtEntry: matchedAtEntry,
            tail: tail,
            cursor: cursor,
            seconds: seconds
        )
    }
}

/// Why waiting for pane output failed before it produced an outcome.
public enum OutputWaitError: Error, Sendable, Hashable {
    case tmux(TmuxError)
    case matching(RegexMatchError)
}

extension Server {
    /// Waits until a pane prints something, driven by tmux output events.
    ///
    /// tmux has no hook that fires on pane output, so a wait that only has
    /// commands to work with must re-read the pane on a timer. A control
    /// connection is told instead: `%output` arrives as the pane writes.
    ///
    /// What arrives there is raw terminal bytes — keystroke echo, escape
    /// sequences, a word split across two notifications — so it is used as a
    /// doorbell rather than as text. Each burst wakes one capture, and the
    /// matching runs against the rendered grid, which is the same text a
    /// person reads. That keeps the accuracy of a capture and pays for it only
    /// when something actually happened. A small liveness probe runs while the
    /// pane is quiet so removing it ends the wait instead of looking like a
    /// timeout.
    ///
    /// The conditions are checked before they are blocked on. A match or stop
    /// already on screen returns at once, with ``OutputWait/matchedAtEntry``
    /// set. Pass `requiringFreshOutput` when only a new occurrence counts.
    ///
    /// - Parameters:
    ///   - pane: the pane to watch.
    ///   - patterns: bounded regular expressions, any of which ends the wait. Empty
    ///     means any new output at all does — the right choice when what the
    ///     pane prints is not known in advance.
    ///   - stops: bounded regular expressions that end the wait as
    ///     ``OutputWait/Outcome/stopped``. A failure marker belongs here: a
    ///     build that fails at five seconds should not hold the wait open for
    ///     the rest of the timeout.
    ///   - requireFresh: only count output that arrives after this call, so a
    ///     match already on screen is waited past rather than returned.
    ///   - cursor: where an earlier incremental capture or wait stopped. Rows
    ///     after it are checked before waiting for more output.
    ///   - timeout: how long to wait before giving up.
    ///   - tailLimit: how many trailing lines to report back.
    public func waitForOutput(
        in pane: Pane,
        matching patterns: [RegexPattern] = [],
        stoppingAt stops: [RegexPattern] = [],
        requiringFreshOutput requireFresh: Bool = false,
        startingAt cursor: CaptureCursor? = nil,
        timeout: Duration = .seconds(30),
        tailLimit: Int = 20
    ) async throws(OutputWaitError) -> OutputWait {
        do {
            _ = try expectedIncarnation([pane.incarnation])
        } catch {
            throw .tmux(error)
        }
        if let cursor {
            guard cursor.pane == pane.id.rawValue else {
                throw .tmux(.foreignServerValue)
            }
            guard cursor.incarnation == pane.incarnation else {
                throw .tmux(.serverRestarted)
            }
        }
        let started = ContinuousClock.now
        return try await OutputWaitSession(
            server: self,
            pane: pane,
            patterns: patterns,
            stops: stops,
            requireFresh: requireFresh,
            startingCursor: cursor,
            started: started,
            deadline: started.advanced(by: timeout),
            tailLimit: max(0, tailLimit)
        ).run()
    }
}

Sources/LibTmux/Watch.swift.content:
import Foundation

/// A format tmux reports changes to, rather than being asked for.
///
/// `refresh-client -B` registers one against a control connection. tmux then
/// evaluates the format about once a second and sends
/// ``SubscriptionChange`` whenever the value differs from the last one it
/// sent — so "has the foreground command changed?" costs no commands, no
/// captures, and no scrollback at all.
///
/// Requires tmux 3.2 or later, which is this package's floor.
public struct FormatSubscription: Sendable, Hashable {
    /// What tmux evaluates the format against.
    public enum Scope: Sendable, Hashable {
        /// The session the connection attached to.
        case attachedSession
        /// One pane, by id.
        case pane(PaneID)
        /// Every pane in the attached session, including ones opened later.
        case allPanes
        /// One window, by id.
        case window(WindowID)
        /// Every window in the attached session, including ones opened later.
        case allWindows

        var wireForm: String {
            switch self {
            case .attachedSession: ""
            case let .pane(id): id.rawValue
            case .allPanes: "%*"
            case let .window(id): id.rawValue
            case .allWindows: "@*"
            }
        }
    }

    /// What changes are reported under, and what
    /// ``ControlSession/stopWatching(_:)`` names.
    public let name: String
    public let scope: Scope
    /// A tmux format, such as `#{pane_current_command}`.
    public let format: String

    public init(name: String, scope: Scope = .allPanes, format: String) {
        self.name = name
        self.scope = scope
        self.format = format
    }

    var argument: String { "\(name):\(scope.wireForm):\(format)" }
}

/// One report that a subscribed format's value changed.
///
/// tmux sends the value it changed *to*, not what it changed from, and sends
/// the current value once when the subscription is created. A watcher
/// therefore learns the starting value without asking for it.
public struct SubscriptionChange: Sendable, Hashable, Codable {
    /// Which ``FormatSubscription`` this belongs to.
    public let name: String
    public let sessionID: SessionID
    /// Absent when the subscription's scope is a session.
    public let windowID: WindowID?
    public let windowIndex: Int?
    /// Absent when the subscription's scope is a session or a window.
    public let paneID: PaneID?
    /// What the format evaluates to now.
    public let value: String

    public init(
        name: String,
        sessionID: SessionID,
        windowID: WindowID? = nil,
        windowIndex: Int? = nil,
        paneID: PaneID? = nil,
        value: String
    ) {
        self.name = name
        self.sessionID = sessionID
        self.windowID = windowID
        self.windowIndex = windowIndex
        self.paneID = paneID
        self.value = value
    }

    /// Reads a `%subscription-changed` notification, or `nil` for any other.
    ///
    /// The wire form is `name session window index pane [reserved...] : value`.
    /// tmux documents everything between the pane id and a lone `:` as
    /// reserved, so the `:` is what the value is found by rather than a field
    /// count that a later release would change.
    public init?(_ notification: ControlNotification) {
        guard notification.name == "subscription-changed" else { return nil }
        let fields = notification.arguments.split(
            separator: " ",
            omittingEmptySubsequences: false
        )
        guard let separator = fields.firstIndex(of: ":"), separator >= 5 else {
            return nil
        }
        func optionalID<ID: TmuxID>(_ index: Int, as _: ID.Type) -> ID?? {
            let field = String(fields[index])
            if field == "-" { return .some(nil) }
            guard let id = ID(rawValue: field) else { return nil }
            return .some(id)
        }
        func optionalIndex(_ index: Int) -> Int?? {
            let field = String(fields[index])
            if field == "-" { return .some(nil) }
            guard let value = Int(field), value >= 0 else { return nil }
            return .some(value)
        }
        guard
            let sessionID = SessionID(rawValue: String(fields[1])),
            let windowID = optionalID(2, as: WindowID.self),
            let windowIndex = optionalIndex(3),
            let paneID = optionalID(4, as: PaneID.self)
        else { return nil }
        self.init(
            name: String(fields[0]),
            sessionID: sessionID,
            windowID: windowID,
            windowIndex: windowIndex,
            paneID: paneID,
            value: fields[(separator + 1)...].joined(separator: " ")
        )
    }
}

/// A lazy view of subscription changes from one bounded notification observer.
public typealias SubscriptionChangeStream = AsyncCompactMapSequence<
    ControlNotificationStream, SubscriptionChange
>

extension ControlSession {
    /// Registers a format subscription on this connection.
    public func watch(_ subscription: FormatSubscription) async throws(TmuxError) {
        let reply = try await send(
            TmuxCommand("refresh-client", ["-B", subscription.argument])
        )
        guard !reply.isError else {
            throw TmuxError.invocationFailed(reason: reply.lines.joined(separator: "\n"))
        }
    }

    /// Removes the subscription registered under `name`.
    ///
    /// tmux reads a `-B` argument with no scope and no format as a removal, so
    /// this is the same command with the rest left off.
    public func stopWatching(_ name: String) async throws(TmuxError) {
        _ = try await send(TmuxCommand("refresh-client", ["-B", name]))
    }

    /// Every subscription change on this connection, optionally narrowed to
    /// one subscription's name.
    ///
    /// An observer of its own, like ``notifications``, so watching does not
    /// take notifications away from anything else reading the connection.
    public nonisolated func changes(named name: String? = nil) -> SubscriptionChangeStream {
        notifications.compactMap { notification in
            guard let change = SubscriptionChange(notification) else { return nil }
            guard name == nil || change.name == name else { return nil }
            return change
        }
    }
}

